UPDATE companies SET description='PakTech is headquartered in Eugene, Oregon, and was founded in 1991 as a family-owned business. The company began as a job shop producing molds for injection-molding firms before pivoting to manufacturing injection-molded recycled handles for the beverage industry.

Today PakTech designs and manufactures 100% recyclable injection-molded handles made from 100% recycled HDPE, along with automated in-line application equipment for turn-key packaging systems. The operation processes post-consumer HDPE — such as milk jugs — through shredding, extrusion, and pelletizing, and has repurposed over half a billion gallon-sized jugs since 2012, diverting roughly 80 million pounds of plastic from landfills and oceans.

The company serves food, beverage, consumer-goods, and household-product manufacturers, from multinational corporations to start-up craft breweries. Its handles multi-pack products including soft drinks, beer, wine, cider, kombucha, craft cocktails, coffee, juice, water, cleaning supplies, and health-and-beauty items. Customers such as Fast Track Packaging and Cape May Brewing Company have cited reliable equipment and responsive service.

PakTech emphasizes that its 100% recycled and recyclable HDPE handles generate 78% fewer greenhouse gases, use 90% less energy, and eliminate virgin petroleum use compared with virgin plastic. The recycled content is certified by SCS Global Services, and the firm partners with more than 500 collection sites to close the loop, turning used handles into park benches, planter pots, and new PakTech products.', certifications=ARRAY['SCS Global Services recycled content certification']::text[], profile='{"capabilities": ["Injection molding", "Extrusion and pelletizing of recycled HDPE", "Recycled HDPE shredding and washing", "Automated applicator manufacturing", "Packaging handle design", "Turn-key packaging system integration"], "industries": ["Food", "Beverage", "Consumer goods", "Household products", "Packaging"], "materials": ["100% recycled HDPE (high-density polyethylene)", "Post-consumer HDPE (milk jugs)"], "equipment": ["Automated in-line applicators (PakTech applicators)"], "volume": "", "lead_time": "", "tolerances": "", "built_on": ["100% recycled and recyclable HDPE handles certified by SCS Global Services", "Automated in-line applicators for turn-key packaging lines", "Circular recycling network with over 500 partner collection sites", "Family-owned since 1991, all products made in Eugene, Oregon", "Handles repurpose post-consumer milk jugs, reducing greenhouse gases by 78%"], "facts_used": ["Founded in 1991 -> /about", "Family-owned -> /about", "Headquartered in Eugene, Oregon -> /about, db", "Designer and manufacturer of injection molded handles from 100% recycled HDPE -> /about", "Automated in-line application equipment -> /about", "Industries: food, beverage, consumer goods, household products -> /about, /", "Recycled content certified by SCS Global Services -> /", "Over 500 recycling partner sites -> description, /", "Repurposed over half a billion milk jugs since 2012 -> description", "80 million pounds diverted from waste stream -> description", "78% less greenhouse gases, 90% less energy, 100% reduction in virgin petroleum -> description", "Testimonials from Fast Track Packaging and Cape May Brewing Company -> /", "Mission: smart packaging handles, automated equipment, superior products, customer service, long-term partnership -> /about", "Core values: customer service, environmental stewardship, quality, innovation, positive work culture -> /about", "Originally a job shop making molds for injection-molding companies -> /about"], "company_type": "Manufacturer", "makes_products": "yes", "type_evidence": "PakTech is a designer and manufacturer of 100% recyclable injection molded handles made from 100% recycled HDPE for the food, beverage, and consumer goods industries.", "founded_year": "1991", "employee_count": "", "cage_code": "", "min_order": "", "export_compliance": [], "languages": [], "social_links": [], "ownership_tags": ["Family-owned"]}'::jsonb, updated_at=now() WHERE slug='paktech' AND approved AND profile IS NULL;
