UPDATE companies SET description='Phoenix-Lamar Corporation was founded in 1972 by Maitland Huffman in Austin, Texas. Huffman, an electronics enthusiast with multiple degrees, established the company as a family-oriented business focused on custom cable and wire harness manufacturing.

The company specializes in custom molded cable assemblies, electrical cables, and wire harnesses, offering in-house design, engineering, prototyping, injection molding, and turnkey assembly. Its production ranges from simple motherboard jumpers to complex 12-mile control cables, with every assembly undergoing 100% electrical testing.

Phoenix-Lamar serves industries including computer and electronics manufacturers, telecommunications, medical diagnostics, biomedical, instrumentation, traffic control, environmental testing, and contract manufacturers. Notable clients include National Instruments, which named the company Supplier of the Year.

The company emphasizes near-zero non-conforming assemblies, UL approval, and a quality system that separates inspection from production to ensure objectivity. Its culture stresses early deliveries, precision workmanship, and long-term employee retention, with many staff members staying for decades.', certifications=ARRAY['ISO 9001:2015','IPC/WHMA-A-620','AS9100','UL approved']::text[], profile='{"capabilities": ["In-house design and engineering", "Prototyping", "Turnkey assembly", "Injection molding", "Custom wire harness design", "Custom molded cable assembly manufacturing", "Electrical cable manufacturing", "100% electrical testing", "Quality inspection per IPC/WHMA-A-620"], "industries": ["Computer/electronics", "Contract manufacturing", "Environmental testing", "Medical diagnostics", "Instrumentation", "Traffic control", "Telecommunications", "Biomedical", "Health care services", "Software companies"], "materials": [], "equipment": [], "volume": "", "lead_time": "", "tolerances": "", "built_on": ["Little to no non-conforming cable assemblies", "UL-approved cable manufacturer", "100% electrical testing on all prototype and production runs", "Separate quality control and production departments for independent inspection", "In-house certified trainer for IPC/WHMA-A-620 and AS9100"], "facts_used": ["Founded in 1972 by Maitland Huffman -> /about-us", "Headquartered in Austin, Texas -> db", "Certifications: ISO 9001:2015, IPC/WHMA-A-620, AS9100, UL approved -> /quality, db", "Capabilities: in-house design, prototyping, turnkey assembly, injection molding, custom wire harness design -> db, /", "Industries served: computer/electronics, contract manufacturing, environmental testing, medical diagnostics, instrumentation, traffic control, telecommunications, biomedical, health care services, software companies -> /, /about-us", "Products: custom molded cable assemblies, electrical cables, wire harnesses -> /", "100% electrical testing on all assemblies -> /quality", "Separate quality control and production departments -> /quality", "Supplier of the Year from National Instruments -> /", "In-house trainer for certifications -> /", "Employees stay for decades -> /about-us", "Global reach 200+, 150+ satisfied clients -> /"], "company_type": "Contract manufacturer / job shop", "makes_products": "yes", "type_evidence": "Phoenix-Lamar Corporation is a manufacturer of custom electrical and electronic cables, wire harnesses, plus connector cable assemblies.", "founded_year": "1972", "employee_count": "", "cage_code": "", "min_order": "", "export_compliance": [], "languages": [], "social_links": ["https://www.linkedin.com/company/phoenix-lamar"], "ownership_tags": []}'::jsonb, updated_at=now() WHERE slug='phoenix-lamar-corporation' AND approved AND profile IS NULL;
UPDATE companies SET description='Piedmont Food Processing Center operates in Hillsborough, North Carolina. Founded in 2018 as a North Carolina non‑profit, the organization grew out of a shared‑kitchen facility established in 2011 through a joint project of Alamance, Chatham, Durham, and Orange counties. The center provides management services to shared‑use kitchens across the state.

The Hillsborough site houses four commercial kitchens that are rented exclusively to one client at a time, with 24‑hour, seven‑day‑a‑week access. The facility also offers dry, refrigerated, and frozen storage that meets Good Manufacturing Practices (GMP) standards. Since opening, the incubator has served roughly 500 food businesses, currently supports about 75 clients, and is credited with generating 180 jobs and more than $3 million in annual retail value each year.

Clients range from first‑time entrepreneurs to established professionals producing packaged foods, running catering and meal‑prep operations, or launching food trucks. The center works closely with regulatory bodies including the NCDA, Orange County Health Department, USDA, FDA, OSHA, and the Department of Homeland Security to help clients navigate compliance.

The organization emphasizes a low‑risk entry model: no annual fees or contracts, exclusive kitchen use during reserved blocks, and hands‑on business development support. It also highlights a focus on women food entrepreneurs and a community of approachable expertise that helps clients move from concept to market.', certifications=ARRAY['GMP']::text[], profile='{"capabilities": ["Shared-use commercial kitchen rental", "Dry storage", "Refrigerated storage", "Frozen storage", "Business development support", "Regulatory compliance assistance", "Food safety consulting"], "industries": ["Packaged food manufacturing", "Catering and meal preparation", "Food truck operations", "Food entrepreneurship"], "materials": [], "equipment": [], "volume": "", "lead_time": "", "tolerances": "", "built_on": ["No annual fees or contracts", "24/7 facility access with exclusive kitchen use", "GMP\u2011compliant dry, refrigerated, and frozen storage", "Direct coordination with NCDA, USDA, FDA, and other regulators", "Business development and regulatory guidance for food startups"], "facts_used": ["Hillsborough, North Carolina location -> db", "Founded 2018 -> db", "Non-profit status -> /about", "Facility established 2011 as joint county project -> /about", "Four kitchens, exclusive use, 24/7 access -> /", "Dry, refrigerated, frozen storage meeting GMP -> /", "500 companies served, 75 current clients, 180 jobs annually, $3M annual retail value -> /", "70% clients still operating since 2018 -> /", "Serves packaged food, catering, meal prep, food truck entrepreneurs -> /", "Works with NCDA, Orange County Health Dept, USDA, FDA, OSHA, DHS -> /", "No annual fees or contracts -> /", "Business development support -> /", "Proud supporter of women food entrepreneurs -> /", "Executive Director Sue Ellsworth -> /about", "Board of Directors and strategic partners listed -> /about", "Funding sources listed -> /about"], "company_type": "Installer / service company", "makes_products": "no", "type_evidence